/* Revolution Slider Slide Animations Extension Stub */
(function(){var R=window.jQuery&&jQuery.fn.revolution;if(!R)return;
R.animateSlide=function(t,trans,container,opt,next,curr,nextH,currH,mtl){
	if(typeof punchgs!=="undefined"&&punchgs.TweenLite){
		// Use masterspeed from next slide data, fallback to 1000ms (1s)
		var speed=(next&&next.data("masterspeed")?parseInt(next.data("masterspeed"),10):1000)/1000;
		if(curr&&curr.length){
			mtl.add(punchgs.TweenLite.to(curr,speed,{autoAlpha:0,ease:punchgs.Power2.easeInOut}),0);
		}
		mtl.add(punchgs.TweenLite.fromTo(next,speed,{autoAlpha:0},{autoAlpha:1,ease:punchgs.Power2.easeInOut}),0);
	}
	return mtl;
}})();
